templateStructure.mainTemplate:
---
title: {{ title }}
preheader: {{ preheader }}

header:
  logoImage: {{ header.logoImage }}
  logoLink: {{ header.logoLink }}

hero:
  gifUrl: {{ hero.gifUrl }}

issue:
  number: {{ issue.number }}

editorial:
  content: {{ editorial.content }}

links:
  items: {{ links.items }}

categories:
- title: {{ category.title }}
  featuredImage: {{ category.featuredImage }}
  description: {{ category.description }}

brands:
  headerImage: {{ brands.headerImage }}
  introText: {{ brands.introText }}
  brandList: {{ brands.brandList }}

social:
  handle: {{ social.handle }}
  linkUrl: {{ social.linkUrl }}

footer:
  socialLinks: {{ footer.socialLinks }}
  companyInfo: {{ footer.companyInfo }}
  subscriptionInfo: {{ footer.subscriptionInfo }}
  unsubscribeLink: {{ footer.unsubscribeLink }}
---

<extends src="src/layouts/main.html">
  <block name="template">
    <component src="src/components/header.html"></component>
    <component src="src/components/animated-hero.html"></component>
    <component src="src/components/issue-header.html"></component>
    <component src="src/components/editorial.html"></component>
    <component src="src/components/link-list.html"></component>
    <each loop="category in categories">
      <component src="src/components/lifestyle-category.html"></component>
    </each>
    <component src="src/components/brand-directory.html"></component>
    <component src="src/components/social-cta.html"></component>
    <component src="src/components/footer.html"></component>
  </block>
</extends>
